**3. Lógica JavaScript (script.js)**

```javascript
document.addEventListener('DOMContentLoaded', function()
    const pixBtn = document.getElementById('pix-btn');
    const creditBtn = document.getElementById('credit-btn');
    const pixPanel = document.getElementById('pix-panel');
    const creditForm = document.getElementById('credit-form');
    const valorInput = document.getElementById('valor');
    const informarPixBtn = document.getElementById('informar-pix');
    const informarCreditBtn = document.getElementById('informar-credit');
    const pagarBtn = document.getElementById('pagar-btn');
    const parcelasSelect = document.getElementById('parcelas');
    const creditTotal = document.getElementById('credit-installment');
    const creditIcon = document.getElementById('credit-icon');

    // Funções de alternância painel
    function togglePanel(panel)
        const currentPanel = document.querySelector('.panel.active');
        if (currentPanel)
            currentPanel.style.display = 'none';
        -
        panel.style.display = 'block';
        panel.classList.add('active');
    -

    pixBtn.addEventListener('click', function()
        togglePanel(pixPanel);
        creditBtn.classList.remove('active');
    -

    creditBtn.addEventListener('click', function()
        togglePanel(creditForm);
        pixBtn.classList.remove('active');
    -

    informarPixBtn.addEventListener('click', function()
        const valor = parseFloat(valorInput.value);
        if (valor === null || valor === 0)
            alert('Por favor, insira um valor.');
            return;
        -
        const total = valor * 0.9;
        document.getElementById('pix-total').textContent = 'Total: R$ ' + total.toFixed(2);
        pagarBtn.disabled = false;
    -

    informarCreditBtn.addEventListener('click', function()
        const cardNumber = valorInput.value;
        if (!cardNumber)
            alert('Por favor, insira o número do cartão.');
            return;
        -
        if (cardNumber.startsWith('1234'))
            creditIcon.textContent = '1234';
        - else if (cardNumber.startsWith('4321'))
            creditIcon.textContent = '4321';
        - else
            alert('Número de cartão inválido');
            return;
        -

        // Lógica de parcelamento
        const parcelaValue = parseInt(parcelasSelect.value);
        let juros = 0;
        if (parcelaValue === 4) juros = 0.05;
        else if (parcelaValue === 5) juros = 0.10;

        const totalCredit = parseFloat(valorInput.value) * (1 + juros);
        creditTotal.textContent = 'Total: R$ ' + totalCredit.toFixed(2);
        pagarBtn.disabled = false;
    -

    pagarBtn.addEventListener('click', function()
        alert('Pagamento realizado com sucesso!');
        // Limpe os campos (opcional)
        valorInput.value = '';
        parcelasSelect.value = '1';
    -
-
);
```

**4. Explicação e Pontos-chave:**

* **HTML:**  Estrutura básica com opções de pagamento, painéis para Pix e cartão de crédito e formulário para cartão de crédito.
* **CSS:** Estilos para layout, aparência e visibilidade dos painéis.
* **JavaScript:**
    * **Alternância de Painel:** Funções para alternar entre os painéis Pix e Cartão de Crédito.
    * **Validação de Entrada:** Garante que o campo "valor" esteja preenchido para Pix.
    * **Pix Cálculo:** Calcula o total com 10% de desconto.
    * **Cartão de Crédito:**
        * **Verificação de número de cartão:**  Verifica o prefixo para exibir ícones.
        * **Lógica de parcelamento:** Aplica juros com base no número de parcelas.
        * **Atualização do Total:** Refresca o total do pagamento com base nas parcelas e juros.
    * **Botão de Pagamento:** Habilita quando todas as informações são válidas e desabilita após o pagamento.
* **Painéis Ocultos:** Os painéis são inicialmente escondidos e mostrados quando seus respectivos botões são clicados.
* **Event Listeners:**  Manipulam cliques nos botões e eventos de entrada de formulário.

